-- ============================================================================
-- INSERT statements for public.leads, generated from merged_leads_2026-08-21_new_only.csv
-- 9263 rows, batched 500 rows per INSERT (19 statements).
-- epos_code is UNIQUE, so ON CONFLICT (epos_code) DO NOTHING - a row that
-- already exists is skipped instead of aborting the whole batch.
-- pic1_phone_clean/pic2_phone_clean/pic3_phone_clean are intentionally absent
-- from the column list - their default clean_phone(picN_contact_number)
-- computes them, so omitting the column lets that default run.
-- epos_code is assigned live from epos_seq (EPOS + 6-digit); company_code is
-- assigned per unique UEN (reusing production's existing code if the UEN is
-- already known, else a fresh company_seq value) - see generate_insert.py.
-- ============================================================================

BEGIN;

-- Abort before consuming any epos_seq values if this batch would breach
-- the 999999 ceiling (see server/inc/func_utilities.py get_next_codes()).
DO $$
DECLARE
  current_val bigint;
BEGIN
  SELECT last_value INTO current_val FROM epos_seq;
  IF current_val + 9263 > 999999 THEN
    RAISE EXCEPTION 'epos_seq ceiling risk: current value %, this batch needs 9263 more, would exceed 999999', current_val;
  END IF;
END $$;

-- Assign one company_code per UEN in this batch: reuse the company_code
-- already on file for that UEN in production leads (if any), else allocate
-- a fresh one from company_seq. Mirrors the reuse rule in
-- server/inc/sg/func_leads.py's create_lead (same UEN -> same company_code).
CREATE TEMP TABLE _import_uens (uen_number text PRIMARY KEY);

