CREATE TEMP TABLE _uen_company_code AS
SELECT iu.uen_number,
       COALESCE(
         (SELECT l.company_code FROM public.leads l
          WHERE l.uen_number = iu.uen_number AND l.company_code IS NOT NULL LIMIT 1),
         'COM' || lpad(nextval('company_seq')::text, 6, '0')
       ) AS company_code
FROM _import_uens iu;

CREATE UNIQUE INDEX ON _uen_company_code (uen_number);

